mapper.update:
WITH expired AS (
    SELECT id
    FROM ai_model_usage
    WHERE billing_status = #{reservedStatus,jdbcType=SMALLINT}
      AND created_at <= #{createdBefore,jdbcType=TIMESTAMP_WITH_TIMEZONE}
    ORDER BY created_at ASC, id ASC
    LIMIT #{batchSize,jdbcType=INTEGER}
    FOR UPDATE SKIP LOCKED
)
UPDATE ai_model_usage usage
SET billing_status = #{reconcileStatus,jdbcType=SMALLINT},
    failure_code = #{failureCode,jdbcType=VARCHAR},
    settled_at = #{settledAt,jdbcType=TIMESTAMP_WITH_TIMEZONE}
FROM expired
WHERE usage.id = expired.id
  AND usage.billing_status = #{reservedStatus,jdbcType=SMALLINT}

mapper.select:
SELECT usage.id AS usage_id, usage.login_identity_id, detail.reserved_quota_minor FROM ai_model_usage usage JOIN ai_model_usage_detail detail ON detail.usage_id = usage.id WHERE usage.billing_status = #{reconcileStatus,jdbcType=SMALLINT} AND (usage.charged_quota_minor IS NULL OR usage.charged_quota_minor = 0) AND usage.failure_code IN
#{failureCode,jdbcType=VARCHAR}
AND detail.conversation_message_id IS NULL AND detail.settlement_delta_minor IS NULL AND detail.reserved_quota_minor > 0 ORDER BY usage.created_at ASC, usage.id ASC LIMIT #{batchSize,jdbcType=INTEGER} FOR UPDATE OF usage SKIP LOCKED

mapper.update:
WITH candidate(usage_id) AS ( VALUES
(#{candidate.usageId,jdbcType=BINARY})
) UPDATE ai_model_usage usage SET billing_status = #{refundedStatus,jdbcType=SMALLINT}, charged_quota_minor = 0, finish_reason = 'SYSTEM_FAILURE_REFUNDED', settled_at = #{settledAt,jdbcType=TIMESTAMP_WITH_TIMEZONE} FROM candidate WHERE usage.id = candidate.usage_id AND usage.billing_status = #{reconcileStatus,jdbcType=SMALLINT}
